//! The math grammar against the reference: the committed golden case files
//! (generated by `tests/mathgrammar/gen_cases.mjs` from the reference
//! grammar) must be reproduced exactly, and the source map must rebuild every
//! text. `JNV_MATHGRAMMAR_CASES` names a freshly generated case file that
//! `fresh_cases_from_env` checks the same way, ending the run with a report
//! when `JNV_MATHGRAMMAR_STALL_SECS` (default 120) pass with no document done.

#[path = "support/casefile.rs"]
mod casefile;

use casefile::{esc, golden, Doc};
use jupynvim::mathgrammar::{
    extract_document, extract_math, jsstr, katex_newcommand, normalize_newlines, prepare_document,
    Engine, EngineTex, Extracted, Kind, MacroScope, Math, PreparedDoc, KATEX_ONLY,
};
use std::collections::HashSet;
use std::io::Write;
use std::path::Path;
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{mpsc, Arc};
use std::time::{Duration, Instant};

// ---- the case file reader ----

/// `<label> <len>\n<payload>\n`.
fn fld(label: &str, payload: &str) -> String {
    format!("{label} {}\n{payload}\n", payload.len())
}

fn sample_doc_one() -> String {
    let mut s = String::from("doc first doc\n");
    s += &fld("src", "a \u{e9} $x$ \u{1F600}");
    s += &fld("text", "a \u{e9} ZZMTH0001ZZ \u{1F600}");
    s += "math 0 0 0 dollar\n";
    s += &fld("tex", "x");
    s += &fld("raw", "$x$");
    s += &fld("prepared", "x");
    s += &fld("katex", "");
    s += "end\n";
    s
}

fn sample_doc_two() -> String {
    let mut s = String::from("doc second\n");
    s += &fld("src", "");
    s += &fld("src", "```math\n\nend\nmath 0 0 0 dollar\n```");
    s += &fld("text", "");
    s += &fld("text", "ZZDMTH0001ZZ");
    s += "math 1 1 1 fence\n";
    s += &fld("tex", "\nend\nmath 0 0 0 dollar\n");
    s += &fld("raw", "```math\n\nend\nmath 0 0 0 dollar\n```");
    s += &fld("prepared", "p\u{e9}");
    s += &fld("katex", "k\u{3b1}");
    s += &fld("mathjax", "m\u{3b2}");
    s += "end\n";
    s
}

fn sample_file() -> String {
    format!(
        "JNVMATH 2\n{}{}count 2\n",
        sample_doc_one(),
        sample_doc_two()
    )
}

fn err_offset(e: &str) -> usize {
    let rest = e
        .strip_prefix("at byte ")
        .unwrap_or_else(|| panic!("error does not name a byte offset: {e}"));
    rest.split(':')
        .next()
        .unwrap()
        .parse()
        .unwrap_or_else(|_| panic!("bad offset in {e}"))
}

#[test]
fn casefile_reads_and_rejects() {
    let file = sample_file();
    let docs = casefile::parse(file.as_bytes()).expect("the sample parses");
    assert_eq!(docs.len(), 2);

    let d = &docs[0];
    assert_eq!(d.name, "first doc");
    assert_eq!(d.sources, ["a \u{e9} $x$ \u{1F600}"]);
    assert_eq!(d.texts, ["a \u{e9} ZZMTH0001ZZ \u{1F600}"]);
    assert_eq!(d.maths.len(), 1);
    let m = &d.maths[0];
    assert_eq!(
        (m.source, m.display, m.block, m.kind.as_str()),
        (0, false, false, "dollar")
    );
    assert_eq!(
        (
            m.tex.as_str(),
            m.raw.as_str(),
            m.prepared.as_str(),
            m.katex.as_str()
        ),
        ("x", "$x$", "x", "")
    );
    // no `mathjax` field: the MathJax text is the prepared text
    assert_eq!(m.mathjax, "x");

    let d = &docs[1];
    assert_eq!(d.name, "second");
    assert_eq!(d.sources, ["", "```math\n\nend\nmath 0 0 0 dollar\n```"]);
    assert_eq!(d.texts, ["", "ZZDMTH0001ZZ"]);
    assert_eq!(d.maths.len(), 1);
    let m = &d.maths[0];
    assert_eq!(
        (m.source, m.display, m.block, m.kind.as_str()),
        (1, true, true, "fence")
    );
    assert_eq!(m.tex, "\nend\nmath 0 0 0 dollar\n");
    assert_eq!(m.raw, "```math\n\nend\nmath 0 0 0 dollar\n```");
    assert_eq!(
        (m.prepared.as_str(), m.katex.as_str(), m.mathjax.as_str()),
        ("p\u{e9}", "k\u{3b1}", "m\u{3b2}")
    );
    assert_eq!(d.maths_of(0).len(), 0);
    assert_eq!(d.maths_of(1).len(), 1);

    // A payload one byte longer than written swallows the newline: the byte after it is not one.
    let n = "a \u{e9} $x$ \u{1F600}".len();
    let head = format!("src {n}\n");
    assert_eq!(
        file.matches(&head).count(),
        1,
        "the sample's first source has {n} bytes"
    );
    let longer = format!("src {}\n", n + 1);
    let bad = file.replacen(&head, &longer, 1);
    let e = casefile::parse(bad.as_bytes()).expect_err("a wrong length is rejected");
    let want = file.find(&head).unwrap() + longer.len() + n + 1;
    assert_eq!(err_offset(&e), want, "{e}");

    // A payload one byte shorter ends before the newline: the byte after it is not one.
    let shorter = format!("src {}\n", n - 1);
    let bad = file.replacen(&head, &shorter, 1);
    let e = casefile::parse(bad.as_bytes()).expect_err("a short length is rejected");
    let want = file.find(&head).unwrap() + shorter.len() + n - 1;
    assert_eq!(err_offset(&e), want, "{e}");

    // A length that runs past the end of the file.
    let bad = file.replacen(&head, "src 99999\n", 1);
    let e = casefile::parse(bad.as_bytes()).expect_err("a length past the end is rejected");
    assert_eq!(err_offset(&e), bad.len(), "{e}");

    // A missing `end`: the next document's head is found where `end` belongs.
    let bad = file.replacen("end\n", "", 1);
    let e = casefile::parse(bad.as_bytes()).expect_err("a missing end is rejected");
    assert_eq!(err_offset(&e), bad.find("doc second\n").unwrap(), "{e}");

    // A wrong count names the offset of the trailer.
    let bad = file.replace("count 2\n", "count 3\n");
    let e = casefile::parse(bad.as_bytes()).expect_err("a wrong count is rejected");
    assert_eq!(err_offset(&e), bad.find("count 3\n").unwrap(), "{e}");
    assert!(e.contains('3') && e.contains('2'), "{e}");

    // No trailer, text after the trailer, no header, a math that names a source that does not exist.
    let bad = file.replace("count 2\n", "");
    assert!(casefile::parse(bad.as_bytes()).is_err());
    let bad = format!("{file}more\n");
    let e = casefile::parse(bad.as_bytes()).expect_err("text after the trailer is rejected");
    assert_eq!(err_offset(&e), file.len(), "{e}");
    let bad = file.replacen("JNVMATH 2\n", "JNVMATH 1\n", 1);
    assert_eq!(err_offset(&casefile::parse(bad.as_bytes()).unwrap_err()), 0);
    // A `mathjax` field is written only where it differs from `prepared`; one equal to it, or one
    // before the `katex` field, is not the format.
    let m = fld("mathjax", "m\u{3b2}");
    let bad = file.replacen(&m, &fld("mathjax", "p\u{e9}"), 1);
    let e =
        casefile::parse(bad.as_bytes()).expect_err("a mathjax field equal to prepared is rejected");
    assert_eq!(err_offset(&e), file.find(&m).unwrap(), "{e}");
    let k = fld("katex", "k\u{3b1}");
    let bad = file.replacen(&format!("{k}{m}"), &format!("{m}{k}"), 1);
    let e = casefile::parse(bad.as_bytes()).expect_err("a mathjax field before katex is rejected");
    assert_eq!(err_offset(&e), file.find(&k).unwrap(), "{e}");
    let bad = file.replacen("math 0 0 0 dollar", "math 1 0 0 dollar", 1);
    let e = casefile::parse(bad.as_bytes()).expect_err("a math of a missing source is rejected");
    assert_eq!(
        err_offset(&e),
        file.find("math 0 0 0 dollar").unwrap(),
        "{e}"
    );
    let bad = file.replacen("math 0 0 0 dollar", "math 0 2 0 dollar", 1);
    assert!(casefile::parse(bad.as_bytes()).is_err());

    // The escape helper used by the messages.
    assert_eq!(
        esc("a\n\t\r\\\u{e9}\u{1F600}"),
        "a\\n\\t\\r\\\\\\u{e9}\\u{1f600}"
    );
}

#[test]
fn casefile_reads_the_golden_files() {
    for (name, docs) in [
        ("battery.cases", 82),
        ("additions.cases", 11),
        ("fixtures.cases", 39),
        ("fuzz.cases", 1500),
        ("ams.cases", 250),
        ("envs.cases", 400),
        ("d5.cases", 300),
        ("multline.cases", 300),
    ] {
        let loaded = casefile::load(&golden(name));
        assert_eq!(loaded.len(), docs, "{name}");
        assert!(
            loaded
                .iter()
                .all(|d| !d.sources.is_empty() && d.sources.len() == d.texts.len()),
            "{name}"
        );
    }
    let ws = std::fs::read_to_string(golden("js_whitespace.txt")).unwrap();
    assert_eq!(ws.lines().count(), 25);
}

// ---- conformance ----

/// One document that differs from the reference.
struct Mismatch {
    doc: String,
    field: String,
    want: String,
    got: String,
}

/// The two strings cut to a window around their first difference, escaped.
fn windows(want: &str, got: &str) -> (String, String) {
    let first = want
        .bytes()
        .zip(got.bytes())
        .position(|(a, b)| a != b)
        .unwrap_or(want.len().min(got.len()));
    let cut = |s: &str| -> String {
        let mut a = first.saturating_sub(40).min(s.len());
        while !s.is_char_boundary(a) {
            a -= 1;
        }
        let mut b = (first + 120).min(s.len());
        while !s.is_char_boundary(b) {
            b += 1;
        }
        let lead = if a > 0 { "..." } else { "" };
        let tail = if b < s.len() { "..." } else { "" };
        format!("{lead}{}{tail}", esc(&s[a..b]))
    };
    (cut(want), cut(got))
}

fn mismatch(doc: &Doc, field: String, want: &str, got: &str) -> Mismatch {
    let (want, got) = windows(want, got);
    Mismatch {
        doc: doc.name.clone(),
        field,
        want,
        got,
    }
}

fn flat_maths(ex: &[Extracted]) -> Vec<(usize, &jupynvim::mathgrammar::Math)> {
    ex.iter()
        .enumerate()
        .flat_map(|(s, x)| x.maths.iter().map(move |m| (s, m)))
        .collect()
}

/// `text` per source and the flat list of maths (source, display, block, kind, tex, raw).
fn check_text_and_maths(doc: &Doc) -> Option<Mismatch> {
    let srcs: Vec<&str> = doc.sources.iter().map(String::as_str).collect();
    compare_text_and_maths(doc, &extract_document(&srcs))
}

/// The comparison itself, on extraction results.
fn compare_text_and_maths(doc: &Doc, ex: &[Extracted]) -> Option<Mismatch> {
    if ex.len() != doc.sources.len() {
        return Some(mismatch(
            doc,
            "sources".into(),
            &doc.sources.len().to_string(),
            &ex.len().to_string(),
        ));
    }
    for (s, x) in ex.iter().enumerate() {
        if x.text != doc.texts[s] {
            return Some(mismatch(doc, format!("text[{s}]"), &doc.texts[s], &x.text));
        }
    }
    let got = flat_maths(ex);
    if got.len() != doc.maths.len() {
        return Some(mismatch(
            doc,
            "maths.len".into(),
            &doc.maths.len().to_string(),
            &got.len().to_string(),
        ));
    }
    for (i, ((s, m), want)) in got.iter().zip(&doc.maths).enumerate() {
        let checks: [(&str, String, String); 6] = [
            ("source", want.source.to_string(), s.to_string()),
            ("display", want.display.to_string(), m.display.to_string()),
            ("block", want.block.to_string(), m.block.to_string()),
            ("kind", want.kind.clone(), m.kind.as_str().to_string()),
            ("tex", want.tex.clone(), m.tex.clone()),
            ("raw", want.raw.clone(), m.raw.clone()),
        ];
        for (f, w, g) in checks {
            if w != g {
                return Some(mismatch(doc, format!("maths[{i}].{f}"), &w, &g));
            }
        }
    }
    None
}

/// `prepared` and the KaTeX text of every math.
fn check_prepared_and_katex(doc: &Doc) -> Option<Mismatch> {
    let srcs: Vec<&str> = doc.sources.iter().map(String::as_str).collect();
    let ex = extract_document(&srcs);
    compare_prepared(doc, &prepare_document(&ex, Engine::Katex))
}

/// The comparison itself, on a prepared document: the numbering first (so a reported KaTeX mismatch means every
/// `prepared` text of the document matched), then the KaTeX text.
fn compare_prepared(doc: &Doc, p: &PreparedDoc) -> Option<Mismatch> {
    compare_prepared_field(doc, p).or_else(|| compare_katex_field(doc, p))
}

/// The offsets and the `prepared` text of every math: the AMS numbering, labels and references.
fn compare_prepared_field(doc: &Doc, p: &PreparedDoc) -> Option<Mismatch> {
    let offsets = reference_offsets(doc);
    if p.offsets != offsets {
        return Some(mismatch(
            doc,
            "offsets".into(),
            &format!("{offsets:?}"),
            &format!("{:?}", p.offsets),
        ));
    }
    if p.prepared.len() != doc.maths.len() || p.engine.len() != doc.maths.len() {
        let got = format!("{} prepared, {} engine", p.prepared.len(), p.engine.len());
        return Some(mismatch(
            doc,
            "prepared.len".into(),
            &doc.maths.len().to_string(),
            &got,
        ));
    }
    for (i, want) in doc.maths.iter().enumerate() {
        if p.prepared[i] != want.prepared {
            return Some(mismatch(
                doc,
                format!("prepared[{i}]"),
                &want.prepared,
                &p.prepared[i],
            ));
        }
    }
    None
}

/// The KaTeX text of every math (`engine[i].tex`); lengths were checked by `compare_prepared_field`.
fn compare_katex_field(doc: &Doc, p: &PreparedDoc) -> Option<Mismatch> {
    for (i, want) in doc.maths.iter().enumerate() {
        let got = p.engine.get(i).map_or("", |e| e.tex.as_str());
        if got != want.katex {
            return Some(mismatch(doc, format!("katex[{i}]"), &want.katex, got));
        }
    }
    None
}

/// The MathJax text of every math (`engine[i].tex` under `Engine::MathJax`): the reference's numbering with
/// MathJax's starred forms of a numbered `eqnarray` and `multline` (deviation D6) and no `\newcommand` rule; lengths
/// were checked by `compare_prepared_field`.
fn compare_mathjax_field(doc: &Doc, p: &PreparedDoc) -> Option<Mismatch> {
    for (i, want) in doc.maths.iter().enumerate() {
        let got = p.engine.get(i).map_or("", |e| e.tex.as_str());
        if got != want.mathjax {
            return Some(mismatch(doc, format!("mathjax[{i}]"), &want.mathjax, got));
        }
    }
    None
}

/// The comparison of a document prepared for MathJax: `prepared` is the reference's for both engines, then the
/// MathJax text.
fn compare_prepared_mathjax(doc: &Doc, p: &PreparedDoc) -> Option<Mismatch> {
    compare_prepared_field(doc, p).or_else(|| compare_mathjax_field(doc, p))
}

/// `prepared` and the MathJax text of every math.
fn check_prepared_and_mathjax(doc: &Doc) -> Option<Mismatch> {
    let srcs: Vec<&str> = doc.sources.iter().map(String::as_str).collect();
    let ex = extract_document(&srcs);
    compare_prepared_mathjax(doc, &prepare_document(&ex, Engine::MathJax))
}

/// Only the numbering: offsets and `prepared`.
fn check_prepared(doc: &Doc) -> Option<Mismatch> {
    let srcs: Vec<&str> = doc.sources.iter().map(String::as_str).collect();
    let ex = extract_document(&srcs);
    compare_prepared_field(doc, &prepare_document(&ex, Engine::Katex))
}

fn report(what: &str, total: usize, bad: &[Mismatch]) -> String {
    let mut out = format!(
        "{what}: {} of {total} documents differ from the reference\n",
        bad.len()
    );
    for m in bad.iter().take(5) {
        out += &format!(
            "doc {} field {}: want {} got {}\n",
            m.doc, m.field, m.want, m.got
        );
    }
    out
}

fn conformance(golden_name: &str, what: &str, check: fn(&Doc) -> Option<Mismatch>) {
    let docs = casefile::load(&golden(golden_name));
    let bad: Vec<Mismatch> = docs.iter().filter_map(check).collect();
    assert!(
        bad.is_empty(),
        "{}",
        report(&format!("{what} {golden_name}"), docs.len(), &bad)
    );
}

